    /// performant, but it's fine for our purposes.
    pub fn validate_row(&self, row: &Row, update: bool, txn: &impl Transaction) -> Result<()> {
        if row.len() != self.columns.len() {
            return errinput!("invalid row size for table {}", self.name);
