        self.lexer.peek().and_then(|r| r.as_ref().ok()).filter(|t| predicate(t)).map(|_| self.lexer.next().unwrap())
    }

    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
        self.lexer.peek().and_then(|r| r.as_ref().ok()).and_then(f).map(|_| self.lexer.next().unwrap())
